var _ crypto.Stream = (*StreamStub)(nil)

// NewStreamStub returns a double of Stream that reports its failures to tb
// and applies opts. The double checks the expected counts of calls at the
// end of the test. With a nil tb, the double reports nothing.
func NewStreamStub(tb assert.TB, opts ...StreamStubOption) *StreamStub {
	s := &StreamStub{
		OnSum:   &StreamSumStub{MethodStub: stub.NewMethodStub[StreamSumCall](tb, "Stream.Sum")},
		OnReset: &StreamResetStub{MethodStub: stub.NewMethodStub[StreamResetCall](tb, "Stream.Reset")},
		OnClose: &StreamCloseStub{MethodStub: stub.NewMethodStub[StreamCloseCall](tb, "Stream.Close")},
		OnWrite: &StreamWriteStub{MethodStub: stub.NewMethodStub[StreamWriteCall](tb, "Stream.Write")},
	}
	s.group = stub.NewGroup(
		s.OnSum.MethodStub,
		s.OnReset.MethodStub,
		s.OnClose.MethodStub,
		s.OnWrite.MethodStub,
	)
	for _, opt := range opts {
		opt(s)
	}
	if s.strict {
		s.group.StrictAll()
	}
	s.group.Bind(tb)
	return s
}

// NewStreamStubDelayed returns a double whose methods sleep d on clk
// before they return. It applies opts after the clock and the latency.
func NewStreamStubDelayed(tb assert.TB, d time.Duration, clk assert.Clock, opts ...StreamStubOption) *StreamStub {
	return NewStreamStub(tb, append([]StreamStubOption{
		StreamStubWithClock(clk),
		StreamStubWithLatency(d),
	}, opts...)...)
}

// NewStreamStubFailing returns a double on which each call of a method
// that can fail fails with err. It applies opts after the failure.
func NewStreamStubFailing(tb assert.TB, err error, opts ...StreamStubOption) *StreamStub {
	return NewStreamStub(tb, append([]StreamStubOption{StreamStubFailing(err)}, opts...)...)
}

// ResetCalls clears the recorded calls, the counters of the faults and the
// expected counts. It keeps the functions, the fixed results and the faults.
func (s *StreamStub) ResetCalls() {
	s.group.Reset()
}

// invoke returns a call of the function of Func with the arguments, and nil
// where no function is set.
func (s *StreamSumStub) invoke() func() StreamSumReturn {
	if s.fn == nil {
		return nil
	}
	return func() StreamSumReturn {
		r0 := s.fn()
		return StreamSumReturn{Result: r0}
	}
}

// Sum records the call. An armed fault comes first, then the function of
// Func, then the results of Returns, and then the zero values.
func (s *StreamStub) Sum() crypto.Digest {
	call := StreamSumCall{}
	r := stub.Answer(s.OnSum.MethodStub, call, stub.Arms[StreamSumCall, StreamSumReturn]{
		Invoke:   s.OnSum.invoke(),
		Fallback: s.OnSum.fallback,
		Stamp: func(c StreamSumCall, r StreamSumReturn) StreamSumCall {
			c.Result = r.Result
			return c
		},
	})
	return r.Result
}

// invokeVoid returns a call of the function of Func with the arguments, and
// nil where no function is set. The empty struct is the result of a method
// without results.
func (s *StreamResetStub) invokeVoid() func() struct{} {
	if s.fn == nil {
		return nil
	}
	return func() struct{} {
		s.fn()
		return struct{}{}
	}
}

// Reset records the call. An armed fault comes first, then the function of
// Func, then the results of Returns, and then the zero values.
func (s *StreamStub) Reset() {
	call := StreamResetCall{}
	stub.Answer(s.OnReset.MethodStub, call, stub.Arms[StreamResetCall, struct{}]{
		Invoke: s.OnReset.invokeVoid(),
	})
}

// invokeVoid returns a call of the function of Func with the arguments, and
// nil where no function is set. The empty struct is the result of a method
// without results.
func (s *StreamCloseStub) invokeVoid() func() struct{} {
	if s.fn == nil {
		return nil
	}
	return func() struct{} {
		s.fn()
		return struct{}{}
	}
}

// Close records the call. An armed fault comes first, then the function of
// Func, then the results of Returns, and then the zero values.
func (s *StreamStub) Close() {
	call := StreamCloseCall{}
	stub.Answer(s.OnClose.MethodStub, call, stub.Arms[StreamCloseCall, struct{}]{
		Invoke: s.OnClose.invokeVoid(),
	})
}

// invoke returns a call of the function of Func with the arguments, and nil
// where no function is set.
func (s *StreamWriteStub) invoke(p []byte) func() StreamWriteReturn {
	if s.fn == nil {
		return nil
	}
	return func() StreamWriteReturn {
		n, err := s.fn(p)
		return StreamWriteReturn{N: n, Err: err}
	}
}

// Write records the call. An armed fault comes first, then the function of
// Func, then the results of Returns, and then the zero values.
func (s *StreamStub) Write(p []byte) (n int, err error) {
	call := StreamWriteCall{P: p}
	r := stub.Answer(s.OnWrite.MethodStub, call, stub.Arms[StreamWriteCall, StreamWriteReturn]{
		Invoke:   s.OnWrite.invoke(p),
		Fallback: s.OnWrite.fallback,
		Fault:    func(err error) StreamWriteReturn { return StreamWriteReturn{Err: err} },
		Stamp: func(c StreamWriteCall, r StreamWriteReturn) StreamWriteCall {
			c.N = r.N
			c.Err = r.Err
			return c
		},
	})
	return r.N, r.Err
}

